# and taking the leading 64 bits.
kTableMagicNumber = 0xdb4775248b80fb57

# 1-byte type + 32-bit crc
kBlockTrailerSize = 5


# DB contents are stored in a set of blocks, each of which holds a
# sequence of key,value pairs.  Each block may be compressed before
# being stored in a file.  The following enum describes which
# compression method (if any) is used to compress a block.
class CompressionType(Enum):
  # NOTE: do not change the values of existing entries, as these are
  # part of the persistent format on disk.
  kNoCompression = 0x0
  kSnappyCompression = 0x1


class BlockHandle:
  kMaxEncodedLength = 10 + 10

  def __init__(self):
    self._offset = 0
    self._size = 0

  @property
  def offset(self) -> int:
    return self._offset

  def set_offset(self, value: int):
    self._offset = value

  @property
  def size(self) -> int:
    return self._size

  def set_size(self, value: int):
    self._size = value

  def encode_to(self):
    # // Sanity check that all fields have been set
    # assert(offset_ != ~static_cast<uint64>(0));
    assert self._offset != ~np.uint64(0)
    # assert(size_ != ~static_cast<uint64>(0));
    assert self._size != ~np.uint64(0)
    # core::PutVarint64(dst, offset_);
    dst = coding.encode_varint64(self._offset)
    # core::PutVarint64(dst, size_);
    dst = dst + coding.encode_varint64(self._size)
    return dst

  def decode_from(self, input: core.StringPiece):
    ok, self._offset = core.get_varint_64(input)
    if ok:
      ok, self._size = core.get_varint_64(input)
      if ok:
        return
    raise errors.DataLoss("bad block handle")


